statement_tex:
\label{lemma-flat}
Let $M$ be an $R$-module. The following are equivalent:
\begin{enumerate}
\item
\label{item-flat}
$M$ is flat over $R$.
\item
\label{item-injective}
for every injection of $R$-modules $N \subset N'$
the map $N \otimes_R M \to N'\otimes_R M$ is injective.
\item
\label{item-f-ideal}
for every ideal $I \subset R$ the map
$I \otimes_R M \to R \otimes_R M = M$ is injective.
\item
\label{item-ffg-ideal}
for every finitely generated ideal $I \subset R$
the map $I \otimes_R M \to R \otimes_R M = M$ is injective.
\end{enumerate}

\label{lemma-sober-subspace}
Let $X$ be a topological space and let $Y\subset X$.
\begin{enumerate}
\item If $X$ is Kolmogorov then so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is quasi-sober then
so is $Y$.
\item Suppose $Y$ is locally closed in $X$. If $X$ is sober then so is $Y$.
\end{enumerate}

\label{lemma-constructible-neighbourhood-Noetherian}
Let $X$ be a Noetherian topological space.
Let $x \in X$.
Let $E \subset X$ be constructible in $X$.
The following are equivalent:
\begin{enumerate}
\item $E$ is a neighbourhood of $x$, and
\item for every irreducible closed subset $Y$ of $X$ which contains
$x$ the intersection $E \cap Y$ is dense in $Y$.
\end{enumerate}

\label{lemma-separated-permanence}
Permanence properties.
\begin{enumerate}
\item A composition of separated morphisms is separated.
\item A composition of quasi-separated morphisms is quasi-separated.
\item The base change of a separated morphism is separated.
\item The base change of a quasi-separated morphism is quasi-separated.
\item A (fibre) product of separated morphisms is separated.
\item A (fibre) product of quasi-separated morphisms is quasi-separated.
\end{enumerate}

\label{lemma-characterize-normal}
Let $E/F$ be an algebraic extension of fields. Let $\overline{F}$ be an
algebraic closure of $F$. The following are equivalent
\begin{enumerate}
\item $E$ is normal over $F$, and
\item for every pair $\sigma, \sigma' \in \Mor_F(E, \overline{F})$ we
have $\sigma(E) = \sigma'(E)$.
\end{enumerate}

\label{lemma-characterize-domain}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal maximal among the ideals which do not contain a
nonzerodivisor is prime.
\item If $R$ is nonzero and every nonzero prime ideal in $R$
contains a nonzerodivisor, then $R$ is a domain.
\end{enumerate}

\label{lemma-primes-principal}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal $I \subset R$ maximal with respect to not being
principal is prime.
\item If every prime ideal of $R$ is principal, then
every ideal of $R$ is principal.
\end{enumerate}

statement:
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

statement_tex:
\label{lemma-glue}
\begin{slogan}
If you have two locally ringed spaces, and a subspace of the first one
is isomorphic to a subspace of the other, then you can glue them together
into one big locally ringed space.
\end{slogan}
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

statement:
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite limits exist in $\mathcal{C}$.
\item Equalizers and fibre products exist in $\mathcal{C}$.
\end{enumerate}

statement_tex:
\label{lemma-fibre-products-equalizers-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite limits exist in $\mathcal{C}$.
\item Equalizers and fibre products exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-finite-jacobson}
A finite Jacobson space is discrete.
A Jacobson space with finitely many closed points is discrete.

\label{lemma-spec-spectral}
The spectrum of a ring is a spectral space, see Topology, Definition
\ref{topology-definition-spectral-space}.

\label{lemma-image-dense-generic-points}
Let $R \to S$ be a ring map. The following are equivalent:
\begin{enumerate}
\item The kernel of $R \to S$ consists of nilpotent elements.
\item The minimal primes of $R$ are in the image of
$\Spec(S) \to \Spec(R)$.
\item The image of $\Spec(S) \to \Spec(R)$ is dense
in $\Spec(R)$.
\end{enumerate}

\label{lemma-constructions-invertible}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item If $\mathcal{L}$, $\mathcal{N}$ are invertible
$\mathcal{O}_X$-modules, then so is
$\mathcal{L} \otimes_{\mathcal{O}_X} \mathcal{N}$.
\item If $\mathcal{L}$ is an invertible $\mathcal{O}_X$-module, then so is
$\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X)$ and the evaluation map
$\mathcal{L} \otimes_{\mathcal{O}_X}
\SheafHom_{\mathcal{O}_X}(\mathcal{L}, \mathcal{O}_X) \to \mathcal{O}_X$
is an isomorphism.
\end{enumerate}

\label{lemma-irreducible}
Let $X$ be a topological space.
\begin{enumerate}
\item If $T \subset X$ is irreducible so is its closure in $X$.
\item Any irreducible component of $X$ is closed.
\item Any irreducible subset of $X$ is contained in an
irreducible component of $X$.
\item Every point of $X$ is contained in some irreducible component
of $X$, in other words, $X$ is the union of its irreducible components.
\end{enumerate}

statement:
Let $X$ be a topological space.
Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of two quasi-compact opens is quasi-compact.
\end{enumerate}
For a subset $T \subset X$ the following are equivalent:
\begin{enumerate}
\item[(a)] $T$ is an intersection of open and closed subsets of $X$, and
\item[(b)] $T$ is closed in $X$ and is a union of connected components of $X$.
\end{enumerate}

statement_tex:
\label{lemma-closed-union-connected-components}
Let $X$ be a topological space.
Assume
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of two quasi-compact opens is quasi-compact.
\end{enumerate}
For a subset $T \subset X$ the following are equivalent:
\begin{enumerate}
\item[(a)] $T$ is an intersection of open and closed subsets of $X$, and
\item[(b)] $T$ is closed in $X$ and is a union of connected components of $X$.
\end{enumerate}

\label{lemma-easy-ff}
Let $R$ be a ring.
Let $M$ be an $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is faithfully flat, and
\item $M$ is flat and for all $R$-module homomorphisms $\alpha : N \to N'$
we have $\alpha = 0$ if and only if $\alpha \otimes \text{id}_M = 0$.
\end{enumerate}

\label{lemma-glueing-near-closed-point-modules}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\mathcal{O}_S\text{-modules }\mathcal{F}\text{ of finite presentation}
\right\}
\longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\right\}
$$
where on the right hand side we consider triples
consisting of a $\mathcal{O}_U$-module $\mathcal{G}$ of
finite presentation, a $\mathcal{O}_{\Spec(\mathcal{O}_{S, s})}$-module
$\mathcal{H}$ of finite presentation, and an isomorphism
$\alpha : \mathcal{G}|_V \to \mathcal{H}|_V$ of
$\mathcal{O}_V$-modules.

\label{proposition-approximate}
Let $S$ be a quasi-compact and quasi-separated scheme.
There exist a directed set $I$
and an inverse system of schemes $(S_i, f_{ii'})$ over $I$
such that
\begin{enumerate}
\item the transition morphisms $f_{ii'}$ are affine
\item each $S_i$ is of finite type over $\mathbf{Z}$, and
\item $S = \lim_i S_i$.
\end{enumerate}

\label{lemma-composition-cartesian}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category over $\mathcal{C}$.
\begin{enumerate}
\item The composition of two strongly cartesian morphisms
is strongly cartesian.
\item Any isomorphism of $\mathcal{S}$ is strongly cartesian.
\item Any strongly cartesian morphism $\varphi$ such that $p(\varphi)$
is an isomorphism, is an isomorphism.
\end{enumerate}

\label{lemma-catenary}
Let $X$ be a topological space.
The following are equivalent:
\begin{enumerate}
\item $X$ is catenary,
\item $X$ has an open covering by catenary spaces.
\end{enumerate}
Moreover, in this case any locally closed subspace of $X$ is catenary.

\label{lemma-normal-case}
Let $E/F$ be a normal algebraic field extension. There exist subextensions
$E / E_{sep} /F$ and $E / E_{insep} / F$ such that
\begin{enumerate}
\item $F \subset E_{sep}$ is Galois and $E_{sep} \subset E$
is purely inseparable,
\item $F \subset E_{insep}$ is purely inseparable and $E_{insep} \subset E$
is Galois,
\item $E = E_{sep} \otimes_F E_{insep}$.
\end{enumerate}

\label{lemma-characterize-local-ring-map}
Let $\varphi : R \to S$ be a ring map. Assume $R$ and $S$ are local rings.
The following are equivalent:
\begin{enumerate}
\item $\varphi$ is a local ring map,
\item $\varphi(\mathfrak m_R) \subset \mathfrak m_S$,
\item $\varphi^{-1}(\mathfrak m_S) = \mathfrak m_R$, and
\item for any $x \in R$, if $\varphi(x)$ is invertible in $S$, then $x$
is invertible in $R$.
\end{enumerate}

\label{lemma-contained-in-radical}
Let $R$ be a ring with Jacobson radical $\text{rad}(R)$.
Let $I \subset R$ be an ideal. The following are
equivalent
\begin{enumerate}
\item $I \subset \text{rad}(R)$, and
\item every element of $1 + I$ is a unit in $R$.
\end{enumerate}
In this case every element of $R$ which maps to a unit of $R/I$ is a unit.

\label{proposition-localize-twice-module}
View $S'^{-1}M$ as an $A$-module, then $S^{-1}(S'^{-1}M)$ is
isomorphic to $(SS')^{-1}M$.

statement:
Let $G$ be a topological group. The following are equivalent
\begin{enumerate}
\item $G$ as a topological space is profinite,
\item $G$ is a limit of a diagram of finite discrete topological groups,
\item $G$ is a cofiltered limit of finite discrete topological groups.
\end{enumerate}

statement_tex:
\label{lemma-profinite-group}
Let $G$ be a topological group. The following are equivalent
\begin{enumerate}
\item $G$ as a topological space is profinite,
\item $G$ is a limit of a diagram of finite discrete topological groups,
\item $G$ is a cofiltered limit of finite discrete topological groups.
\end{enumerate}

statement:
Let $\mathcal{C}$ be a category. Let $F : \mathcal{X} \to \mathcal{Y}$
be a $1$-morphism of fibred categories over $\mathcal{C}$.
There exist $1$-morphisms of fibred categories over $\mathcal{C}$
$$
\xymatrix{
\mathcal{X} \ar@<1ex>[r]^u &
\mathcal{X}' \ar[r]^v \ar@<1ex>[l]^w & \mathcal{Y}
}
$$
such that $F = v \circ u$ and such that
\begin{enumerate}
\item $u : \mathcal{X} \to \mathcal{X}'$ is fully faithful,
\item $w$ is left adjoint to $u$, and
\item $v : \mathcal{X}' \to \mathcal{Y}$ is a fibred category.
\end{enumerate}

statement_tex:
\label{lemma-ameliorate-morphism-fibred-categories}
Let $\mathcal{C}$ be a category. Let $F : \mathcal{X} \to \mathcal{Y}$
be a $1$-morphism of fibred categories over $\mathcal{C}$.
There exist $1$-morphisms of fibred categories over $\mathcal{C}$
$$
\xymatrix{
\mathcal{X} \ar@<1ex>[r]^u &
\mathcal{X}' \ar[r]^v \ar@<1ex>[l]^w & \mathcal{Y}
}
$$
such that $F = v \circ u$ and such that
\begin{enumerate}
\item $u : \mathcal{X} \to \mathcal{X}'$ is fully faithful,
\item $w$ is left adjoint to $u$, and
\item $v : \mathcal{X}' \to \mathcal{Y}$ is a fibred category.
\end{enumerate}

statement:
Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}

statement_tex:
\label{lemma-constructible-stable-specialization-closed}
Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}

\label{lemma-essentially-finite-type-criterion-proper}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a quasi-compact morphism of schemes locally
of finite type over $S$. The following are equivalent
\begin{enumerate}
\item $f$ proper,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists exactly one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking for the existence and uniqueness of the dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-standard-open}
Let $R$ be a ring. Let $f \in R$.
\begin{enumerate}
\item If $g\in R$ and $D(g) \subset D(f)$, then
\begin{enumerate}
\item $f$ is invertible in $R_g$,
\item $g^e = af$ for some $e \geq 1$ and $a \in R$,
\item there is a canonical ring map $R_f \to R_g$, and
\item there is a canonical $R_f$-module map
$M_f \to M_g$ for any $R$-module $M$.
\end{enumerate}
\item Any open covering of $D(f)$ can be refined to a finite
open covering of the form $D(f) = \bigcup_{i = 1}^n D(g_i)$.
\item If $g_1, \ldots, g_n \in R$, then $D(f) \subset \bigcup D(g_i)$
if and only if $g_1, \ldots, g_n$ generate the unit ideal in $R_f$.
\end{enumerate}

\label{lemma-constructible}
The collection of constructible sets is closed under
finite intersections, finite unions and complements.

\label{lemma-describe-limits}
Let $\mathcal{I}$ be a cofiltered category. Let $i \mapsto X_i$ be a diagram
of topological spaces over $\mathcal{I}$. Let $X = \lim X_i$ be the limit
with projection maps $f_i : X \to X_i$.
\begin{enumerate}
\item Any open of $X$ is of the form $\bigcup_{j \in J} f_j^{-1}(U_j)$
for some subset $J \subset I$ and opens $U_j \subset X_j$.
\item Any quasi-compact open of $X$ is of the form
$f_i^{-1}(U_i)$ for some $i$ and some $U_i \subset X_i$ open.
\end{enumerate}

\label{lemma-characterize-constructible-Noetherian}
Let $X$ be a Noetherian topological space.
Let $E \subset X$ be a subset.
The following are equivalent:
\begin{enumerate}
\item $E$ is constructible in $X$, and
\item for every irreducible closed $Z \subset X$ the intersection
$E \cap Z$ either contains a nonempty open of $Z$ or is not dense in $Z$.
\end{enumerate}

\label{lemma-domain-image-dense-set-points-generic-point}
Let $R$ be a domain. Let $\varphi : R \to S$ be a ring map.
The following are equivalent:
\begin{enumerate}
\item The ring map $R \to S$ is injective.
\item The image $\Spec(S) \to \Spec(R)$
contains a dense set of points.
\item There exists a prime ideal $\mathfrak q \subset S$
whose inverse image in $R$ is $(0)$.
\end{enumerate}

\label{lemma-connected-components}
Let $X$ be a topological space.
\begin{enumerate}
\item If $T \subset X$ is connected, then so is its closure.
\item Any connected component of $X$ is closed (but not necessarily open).
\item Every connected subset of $X$ is contained in a unique connected
component of $X$.
\item Every point of $X$ is contained in a unique connected component, in other
words, $X$ is the disjoint union of its connected components.
\end{enumerate}

\label{lemma-affine-separated}
An affine scheme is separated. A morphism from an affine scheme
to another scheme is separated.

\label{lemma-topological-ring-colimits}
The category of topological rings has colimits and colimits commute
with the forgetful functor to the category of rings.

statement:
Let $R \to S$ be a ring map. The following are equivalent:
\begin{enumerate}
\item Going up holds for $R \to S$, and
\item the map $\Spec(S) \to \Spec(R)$ is closed.
\end{enumerate}

statement_tex:
\label{lemma-going-up-closed}
Let $R \to S$ be a ring map. The following are equivalent:
\begin{enumerate}
\item Going up holds for $R \to S$, and
\item the map $\Spec(S) \to \Spec(R)$ is closed.
\end{enumerate}

\label{lemma-pid-jacobson}
The ring $\mathbf{Z}$ is a Jacobson ring.
More generally, let $R$ be a ring such that
\begin{enumerate}
\item $R$ is a domain,
\item $R$ is Noetherian,
\item any nonzero prime ideal is a maximal ideal, and
\item $R$ has infinitely many maximal ideals.
\end{enumerate}
Then $R$ is a Jacobson ring.

statement:
Let $T \subset X$ be a subset of a topological space $X$.
The following are equivalent
\begin{enumerate}
\item $T$ is stable under specialization, and
\item $T$ is a (directed) union of closed subsets of $X$.
\end{enumerate}

statement_tex:
\label{lemma-stable-specialization}
Let $T \subset X$ be a subset of a topological space $X$.
The following are equivalent
\begin{enumerate}
\item $T$ is stable under specialization, and
\item $T$ is a (directed) union of closed subsets of $X$.
\end{enumerate}

\label{lemma-relatively-prime-polynomials}
Two polynomials in $k[x]$ are relatively prime precisely when they
have no common roots in an algebraic closure $\overline{k}$ of $k$.

\label{lemma-ff-rings}
Let $R \to S$ be a flat ring map.
The following are equivalent:
\begin{enumerate}
\item $R \to S$ is faithfully flat,
\item the induced map on $\Spec$ is surjective, and
\item any closed point $x \in \Spec(R)$ is
in the image of the map $\Spec(S) \to \Spec(R)$.
\end{enumerate}

\label{lemma-flat-eq}
A module $M$ over $R$ is flat if and only if
every relation in $M$ is trivial.

\label{lemma-locally-quasi-compact-Hausdorff}
A Hausdorff space is locally quasi-compact if and only if every point
has a quasi-compact neighbourhood.

statement:
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite colimits exist in $\mathcal{C}$.
\item Coequalizers and pushouts exist in $\mathcal{C}$.
\end{enumerate}

statement_tex:
\label{lemma-push-outs-coequalizers-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Connected finite colimits exist in $\mathcal{C}$.
\item Coequalizers and pushouts exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-essentially-finite-type-criterion-separation}
Let $S$ be a Nagata scheme (and in particular locally Noetherian).
Let $f : X \to Y$ be a morphism of schemes locally of finite type over $S$.
The following are equivalent
\begin{enumerate}
\item $f$ separated,
\item for any commutative diagram
$$
\xymatrix{
U \ar[r] \ar[d] & X \ar[d]^f \\
C \ar[r] \ar@{..>}[ru] & Y
}
$$
of schemes over $S$ such that
\begin{enumerate}
\item $C$ is a normal integral scheme of finite type over $S$,
\item $U = C \setminus \{c\}$ for some closed point $c \in C$,
\item $A = \mathcal{O}_{C, c}$ has dimension $1$\footnote{It follows
that $A$ is a discrete valuation ring, see
Algebra, Lemma \ref{algebra-lemma-characterize-dvr}.
Moreover, $c$ maps to a finite type point $s \in S$ and
$A$ is essentially of finite type over $\mathcal{O}_{S, s}$.}
\end{enumerate}
then in the commutative diagram
$$
\xymatrix{
\Spec(K) \ar[r] \ar[d] & X \ar[d]^f \\
\Spec(A) \ar[r] \ar@{-->}[ru] & Y
}
$$
where $K = \text{Frac}(A)$ there exists at most one dotted arrow\footnote{By
Lemma \ref{lemma-morphism-glueing-near-closed-point} this is
equivalent to asking there to be at most one dotted arrow
making the first commutative diagram commute.}
making the diagram commute.
\end{enumerate}

\label{lemma-unique-prime-over-localize-below}
Let $R \to S$ be a ring map.
Let $\mathfrak p \subset R$ be a prime.
Assume that
\begin{enumerate}
\item there exists a unique prime $\mathfrak q \subset S$ lying over
$\mathfrak p$, and
\item either
\begin{enumerate}
\item going up holds for $R \to S$, or
\item going down holds for $R \to S$ and there is at most one prime
of $S$ above every prime of $R$.
\end{enumerate}
\end{enumerate}
Then $S_{\mathfrak p} = S_{\mathfrak q}$.

statement:
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finitely presented $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is bijective.
\end{enumerate}

statement_tex:
\label{lemma-characterize-finitely-presented-module-hom}
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finitely presented $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is bijective.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$.
Assume $Y$ is locally of finite presentation over $S$.
Let $x \in X$ be a closed point such that
$U = X \setminus \{x\} \to X$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}) \setminus \{x\}$ there is
a bijection
$$
\left\{
\begin{matrix}
\text{morphisms }X \to Y\text{ over }S
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(a, b)\text{ where }
a : U \to Y\text{ and }b : \Spec(\mathcal{O}_{X, x}) \to Y\\
\text{ are morphisms over }S
\text{ which agree over }V
\end{matrix}
\right\}
$$

statement_tex:
\label{lemma-morphism-glueing-near-closed-point}
Let $S$ be a scheme. Let $X$ and $Y$ be schemes over $S$.
Assume $Y$ is locally of finite presentation over $S$.
Let $x \in X$ be a closed point such that
$U = X \setminus \{x\} \to X$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{X, x}) \setminus \{x\}$ there is
a bijection
$$
\left\{
\begin{matrix}
\text{morphisms }X \to Y\text{ over }S
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
(a, b)\text{ where }
a : U \to Y\text{ and }b : \Spec(\mathcal{O}_{X, x}) \to Y\\
\text{ are morphisms over }S
\text{ which agree over }V
\end{matrix}
\right\}
$$

statement:
Let $f : X \to S$ be a morphism of schemes.
Consider the diagrams
$$
\vcenter{
\xymatrix{
X_s \ar[r] \ar[d] & X \ar[d] \\
\Spec(\kappa(s)) \ar[r] & S
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Spec(\mathcal{O}_{S, s}) \times_S X \ar[r] \ar[d] & X \ar[d] \\
\Spec(\mathcal{O}_{S, s}) \ar[r] & S
}
}
$$
In both cases these diagrams induce fibre squares of topological
spaces and in particular, the top horizontal arrow is a homeomorphism
onto its image.

statement_tex:
\label{lemma-fibre-topological}
Let $f : X \to S$ be a morphism of schemes.
Consider the diagrams
$$
\vcenter{
\xymatrix{
X_s \ar[r] \ar[d] & X \ar[d] \\
\Spec(\kappa(s)) \ar[r] & S
}
}
\quad\text{and}\quad
\vcenter{
\xymatrix{
\Spec(\mathcal{O}_{S, s}) \times_S X \ar[r] \ar[d] & X \ar[d] \\
\Spec(\mathcal{O}_{S, s}) \ar[r] & S
}
}
$$
In both cases these diagrams induce fibre squares of topological
spaces and in particular, the top horizontal arrow is a homeomorphism
onto its image.

statement:
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ the base change functor
$$
\left\{
\begin{matrix}
f : X \to S\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{S, s})\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

statement_tex:
\label{lemma-modifications}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ the base change functor
$$
\left\{
\begin{matrix}
f : X \to S\text{ of finite presentation} \\
f^{-1}(U) \to U\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
g : Y \to \Spec(\mathcal{O}_{S, s})\text{ of finite presentation} \\
g^{-1}(V) \to V\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

\label{lemma-almost-finite-limits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Nonempty finite limits exist in $\mathcal{C}$.
\item Products of pairs and equalizers exist in $\mathcal{C}$.
\item Products of pairs and fibre products exist in $\mathcal{C}$.
\end{enumerate}

\label{lemma-invertible}
Let $\mathcal{C}$ be a monoidal category. Let $X$ be an object of
$\mathcal{C}$. The following are equivalent
\begin{enumerate}
\item the functor $L : Y \mapsto X \otimes Y$ is an equivalence,
\item the functor $R : Y \mapsto Y \otimes X$ is an equivalence,
\item there exists an object $X'$ such that
$X \otimes X' \cong X' \otimes X \cong \mathbf{1}$.
\end{enumerate}

statement:
Let $X$ be a topological space. The following are equivalent:
\begin{enumerate}
\item $X$ is Hausdorff,
\item the diagonal $\Delta(X) \subset X \times X$ is closed.
\end{enumerate}

statement_tex:
\label{lemma-Hausdorff}
Let $X$ be a topological space. The following are equivalent:
\begin{enumerate}
\item $X$ is Hausdorff,
\item the diagonal $\Delta(X) \subset X \times X$ is closed.
\end{enumerate}

\label{lemma-reduced}
A scheme $X$ is reduced if and only if $\mathcal{O}_X(U)$
is a reduced ring for all $U \subset X$ open.

\label{lemma-colimits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Finite colimits exist in $\mathcal{C}$.
\item Finite coproducts and coequalizers exist in $\mathcal{C}$.
\item The category has an initial object and pushouts exist.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $U \subset S$ be a retrocompact open.
Let $s \in S$ be a point in the complement of $U$. With
$V = \Spec(\mathcal{O}_{S, s}) \cap U$ there is
an equivalence of categories
$$
\colim_{s \in U' \supset U\text{ open}}
\left\{
\vcenter{
\xymatrix{
X \ar[d] \\
U'
}
}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the left hand side the vertical arrow is of finite
presentation and on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

statement_tex:
\label{lemma-glueing-near-point}
Let $S$ be a scheme. Let $U \subset S$ be a retrocompact open.
Let $s \in S$ be a point in the complement of $U$. With
$V = \Spec(\mathcal{O}_{S, s}) \cap U$ there is
an equivalence of categories
$$
\colim_{s \in U' \supset U\text{ open}}
\left\{
\vcenter{
\xymatrix{
X \ar[d] \\
U'
}
}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the left hand side the vertical arrow is of finite
presentation and on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

statement:
Let $L/K$ be a finite extension of fields. The following are equivalent:
\begin{enumerate}
\item $L/K$ is separable,
\item $\text{Trace}_{L/K}$ is not identically zero, and
\item the trace pairing $Q_{L/K}$ is nondegenerate.
\end{enumerate}

statement_tex:
\label{lemma-separable-trace-pairing}
Let $L/K$ be a finite extension of fields. The following are equivalent:
\begin{enumerate}
\item $L/K$ is separable,
\item $\text{Trace}_{L/K}$ is not identically zero, and
\item the trace pairing $Q_{L/K}$ is nondegenerate.
\end{enumerate}

\label{lemma-specializations-lift}
Let $f : X \to S$ be a morphism of schemes.
\begin{enumerate}
\item If $f$ is universally closed then specializations lift
along any base change of $f$, see
Topology, Definition \ref{topology-definition-lift-specializations}.
\item If $f$ is quasi-compact and specializations lift
along any base change of $f$, then $f$ is universally closed.
\end{enumerate}

statement:
Let $f : X \to S$ be a quasi-compact morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f(X) \subset S$ is closed, and
\item $f(X) \subset S$ is stable under specialization.
\end{enumerate}

statement_tex:
\label{lemma-image-quasi-compact-closed}
Let $f : X \to S$ be a quasi-compact morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f(X) \subset S$ is closed, and
\item $f(X) \subset S$ is stable under specialization.
\end{enumerate}

\label{lemma-characterize-open-Noetherian}
Let $X$ be a Noetherian topological space.
Let $E \subset X$ be a subset.
The following are equivalent:
\begin{enumerate}
\item $E$ is open in $X$, and
\item for every irreducible closed subset $Y$ of $X$
the intersection $E \cap Y$ is either empty or
contains a nonempty open of $Y$.
\end{enumerate}

statement:
Let $R$ be a ring. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item If $N$ and $M$ are finite, then so is $M \otimes_R N$.
\item If $N$ and $M$ are finitely presented, then so is $M \otimes_R N$.
\end{enumerate}

statement_tex:
\label{lemma-tensor-finiteness}
Let $R$ be a ring. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item If $N$ and $M$ are finite, then so is $M \otimes_R N$.
\item If $N$ and $M$ are finitely presented, then so is $M \otimes_R N$.
\end{enumerate}

statement:
Let $K/E/F$ be a tower of algebraic field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is separable over $F$, then $\alpha$ is separable
over $E$.
\item if $K$ is separable over $F$, then $K$ is separable over $E$.
\end{enumerate}

statement_tex:
\label{lemma-separable-goes-up}
Let $K/E/F$ be a tower of algebraic field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is separable over $F$, then $\alpha$ is separable
over $E$.
\item if $K$ is separable over $F$, then $K$ is separable over $E$.
\end{enumerate}

statement:
Let $R$ be a Noetherian ring.
\begin{enumerate}
\item Any finite $R$-module is of finite presentation.
\item Any submodule of a finite $R$-module is finite.
\item Any finite type $R$-algebra is of finite presentation over $R$.
\end{enumerate}

statement_tex:
\label{lemma-Noetherian-finite-type-is-finite-presentation}
Let $R$ be a Noetherian ring.
\begin{enumerate}
\item Any finite $R$-module is of finite presentation.
\item Any submodule of a finite $R$-module is finite.
\item Any finite type $R$-algebra is of finite presentation over $R$.
\end{enumerate}

\label{lemma-integral-over-field}
Let $k$ be a field. Let $S$ be a $k$-algebra over $k$.
\begin{enumerate}
\item If $S$ is a domain and finite dimensional over $k$,
then $S$ is a field.
\item If $S$ is integral over $k$ and a domain,
then $S$ is a field.
\item If $S$ is integral over $k$ then every prime of
$S$ is a maximal ideal (see
Lemma \ref{lemma-ring-with-only-minimal-primes}
for more consequences).
\end{enumerate}

statement:
Let $R \to S$ and $R \to R'$ be ring maps.
Set $S' = R' \otimes_R S$.
\begin{enumerate}
\item If $R \to S$ is integral so is $R' \to S'$.
\item If $R \to S$ is finite so is $R' \to S'$.
\end{enumerate}

statement_tex:
\label{lemma-base-change-integral}
\begin{slogan}
Integrality and finiteness are preserved under base change.
\end{slogan}
Let $R \to S$ and $R \to R'$ be ring maps.
Set $S' = R' \otimes_R S$.
\begin{enumerate}
\item If $R \to S$ is integral so is $R' \to S'$.
\item If $R \to S$ is finite so is $R' \to S'$.
\end{enumerate}

\label{lemma-Noetherian-permanence}
\begin{slogan}
Noetherian property is stable by passage to finite type extension
and localization.
\end{slogan}
Any finitely generated ring over a Noetherian ring
is Noetherian. Any localization of a Noetherian ring
is Noetherian.

\label{lemma-lift-specializations-images}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If specializations lift along $f$, and if $T \subset X$
is stable under specialization, then $f(T) \subset Y$ is
stable under specialization.
\item If generalizations lift along $f$, and if $T \subset X$
is stable under generalization, then $f(T) \subset Y$ is
stable under generalization.
\end{enumerate}

\label{lemma-module-quotient-flat}
Let $(X, \mathcal{O}_X)$ be a ringed space.
\begin{enumerate}
\item Any sheaf of $\mathcal{O}_X$-modules is a quotient of
a direct sum $\bigoplus j_{U_i!}\mathcal{O}_{U_i}$.
\item Any $\mathcal{O}_X$-module is a quotient of
a flat $\mathcal{O}_X$-module.
\end{enumerate}

\label{lemma-characterize-reduced-ring-normal}
Let $R$ be a ring. Assume $R$ is reduced and has finitely many
minimal primes. Then the following are equivalent:
\begin{enumerate}
\item $R$ is a normal ring,
\item $R$ is integrally closed in its total ring of fractions, and
\item $R$ is a finite product of normal domains.
\end{enumerate}

\label{lemma-obvious-Noetherian}
Any finite type algebra over a field is Noetherian.
Any finite type algebra over $\mathbf{Z}$ is Noetherian.

\label{lemma-finite-limits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Finite limits exist in $\mathcal{C}$.
\item Finite products and equalizers exist.
\item The category has a final object and fibre products exist.
\end{enumerate}

\label{lemma-flatness-descends-more-general}
Let $R$ be a ring. Let $S \to S'$ be a flat map of $R$-algebras.
Let $M$ be a module over $S$, and set $M' = S' \otimes_S M$.
\begin{enumerate}
\item If $M$ is flat over $R$, then $M'$ is flat over $R$.
\item If $S \to S'$ is faithfully flat, then $M$ is flat
over $R$ if and only if $M'$ is flat over $R$.
\end{enumerate}

\label{lemma-generic-point-in-constructible}
Let $X$ be a topological space. Suppose that
$Z \subset X$ is irreducible. Let $E \subset X$
be a finite union of locally closed subsets (e.g.\ $E$
is constructible). The following are equivalent
\begin{enumerate}
\item The intersection $E \cap Z$ contains an open
dense subset of $Z$.
\item The intersection $E \cap Z$ is dense in $Z$.
\end{enumerate}
If $Z$ has a generic point $\xi$, then this is
also equivalent to
\begin{enumerate}
\item[(3)] We have $\xi \in E$.
\end{enumerate}

\label{lemma-normal-closure-inside-normal}
Let $L/K$ be an algebraic normal extension.
\begin{enumerate}
\item If $L/M/K$ is a subextension with $M/K$ finite, then there exists
a tower $L/M'/M/K$ with $M'/K$ finite and normal.
\item If $L/M'/M/K$ is a tower with $M/K$ normal and $M'/M$ finite,
then there exists a tower $L/M''/M'/M/K$ with $M''/M$
finite and $M''/K$ normal.
\end{enumerate}

\label{lemma-qc-open}
Let $U \subset \Spec(R)$ be open. The following
are equivalent:
\begin{enumerate}
\item $U$ is retrocompact in $\Spec(R)$,
\item $U$ is quasi-compact,
\item $U$ is a finite union of standard opens, and
\item there exists a finitely generated ideal $I \subset R$ such
that $X \setminus V(I) = U$.
\end{enumerate}

statement:
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is quasi-compact, then $f(X)$ is quasi-compact.
\item If $f$ is quasi-compact, then $f(X)$ is retrocompact.
\end{enumerate}

statement_tex:
\label{lemma-image-quasi-compact}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is quasi-compact, then $f(X)$ is quasi-compact.
\item If $f$ is quasi-compact, then $f(X)$ is retrocompact.
\end{enumerate}

statement:
Let $\varphi : R \to S$ be a ring map.
\begin{enumerate}
\item If $\varphi$ is finite, then $\varphi$ is of finite type.
\item If $S$ is of finite presentation as an $R$-module, then
$\varphi$ is of finite presentation.
\end{enumerate}

statement_tex:
\label{lemma-finite-finite-type}
Let $\varphi : R \to S$ be a ring map.
\begin{enumerate}
\item If $\varphi$ is finite, then $\varphi$ is of finite type.
\item If $S$ is of finite presentation as an $R$-module, then
$\varphi$ is of finite presentation.
\end{enumerate}

\label{lemma-normality-is-local}
Let $R$ be a domain. The following are equivalent:
\begin{enumerate}
\item The domain $R$ is a normal domain,
\item for every prime $\mathfrak p \subset R$ the local ring
$R_{\mathfrak p}$ is a normal domain, and
\item for every maximal ideal $\mathfrak m$ the ring $R_{\mathfrak m}$
is a normal domain.
\end{enumerate}

\label{lemma-irreducible-components-containing-x}
Let $R$ be a ring. Let $\mathfrak p \subset R$ be a prime.
\begin{enumerate}
\item the set of irreducible closed subsets of $\Spec(R)$
passing through $\mathfrak p$ is in one-to-one correspondence with
primes $\mathfrak q \subset R_{\mathfrak p}$.
\item The set of irreducible components of $\Spec(R)$ passing through
$\mathfrak p$ is in one-to-one correspondence with minimal
primes $\mathfrak q \subset R_{\mathfrak p}$.
\end{enumerate}

\label{lemma-open-closed-specialization}
Let $X$ be a topological space.
\begin{enumerate}
\item Any closed subset of $X$ is stable under specialization.
\item Any open subset of $X$ is stable under generalization.
\item A subset $T \subset X$ is stable under specialization
if and only if
the complement $T^c$ is stable under generalization.
\end{enumerate}

statement:
Let $R$ be a ring.
\begin{enumerate}
\item For an element $x$ of an $R$-module $M$ the following are equivalent
\begin{enumerate}
\item $x = 0$,
\item $x$ maps to zero in $M_\mathfrak p$ for all $\mathfrak p \in \Spec(R)$,
\item $x$ maps to zero in $M_{\mathfrak m}$ for all maximal ideals
$\mathfrak m$ of $R$.
\end{enumerate}
In other words, the map $M \to \prod_{\mathfrak m} M_{\mathfrak m}$
is injective.
\item Given an $R$-module $M$ the following are equivalent
\begin{enumerate}
\item $M$ is zero,
\item $M_{\mathfrak p}$ is zero for all $\mathfrak p \in \Spec(R)$,
\item $M_{\mathfrak m}$ is zero for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a complex $M_1 \to M_2 \to M_3$
of $R$-modules the following are equivalent
\begin{enumerate}
\item $M_1 \to M_2 \to M_3$ is exact,
\item for every prime $\mathfrak p$ of $R$ the localization
$M_{1, \mathfrak p} \to M_{2, \mathfrak p} \to M_{3, \mathfrak p}$
is exact,
\item for every maximal ideal $\mathfrak m$ of $R$ the localization
$M_{1, \mathfrak m} \to M_{2, \mathfrak m} \to M_{3, \mathfrak m}$
is exact.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is injective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is injective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is injective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is surjective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is surjective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\item Given a map $f : M \to M'$ of $R$-modules the following are equivalent
\begin{enumerate}
\item $f$ is bijective,
\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is bijective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is bijective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-characterize-zero-local}
Let $R$ be a ring.
\begin{enumerate}
\item For an element $x$ of an $R$-module $M$ the following are equivalent
\begin{enumerate}
\item $x = 0$,
\item $x$ maps to zero in $M_\mathfrak p$ for all $\mathfrak p \in \Spec(R)$,
\item $x$ maps to zero in $M_{\mathfrak m}$ for all maximal ideals
