\item $f_{\mathfrak p} : M_\mathfrak p \to M'_\mathfrak p$ is bijective
for all primes $\mathfrak p$ of $R$,
\item $f_{\mathfrak m} : M_\mathfrak m \to M'_\mathfrak m$ is bijective
for all maximal ideals $\mathfrak m$ of $R$.
\end{enumerate}
\end{enumerate}

\label{lemma-characterize-closed-Noetherian}
Let $X$ be a Noetherian sober topological space.
Let $E \subset X$ be a subset of $X$.
\begin{enumerate}
\item If $E$ is constructible and stable under specialization, then
$E$ is closed.
\item If $E$ is constructible and stable under generalization, then
$E$ is open.
\end{enumerate}

\label{lemma-subring-of-local-ring}
Let $R$ be a ring and $\mathfrak p \subset R$ be a prime.
There exists an $f \in R$, $f \not \in \mathfrak p$ such
that $R_f \to R_\mathfrak p$ is injective in each of the
following cases
\begin{enumerate}
\item $R$ is a domain,
\item $R$ is Noetherian, or
\item $R$ is reduced and has finitely many minimal primes.
\end{enumerate}

statement:
Let $K/E/F$ be a tower of field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is algebraic over $F$, then $\alpha$ is algebraic
over $E$.
\item If $K$ is algebraic over $F$, then $K$ is algebraic over $E$.
\end{enumerate}

statement_tex:
\label{lemma-algebraic-goes-up}
Let $K/E/F$ be a tower of field extensions.
\begin{enumerate}
\item If $\alpha \in K$ is algebraic over $F$, then $\alpha$ is algebraic
over $E$.
\item If $K$ is algebraic over $F$, then $K$ is algebraic over $E$.
\end{enumerate}

\label{lemma-lift-maps}
Let $L/M/K$ be a tower of algebraic extensions.
\begin{enumerate}
\item If $M/K$ is normal, then any automorphism $\tau$ of $L/K$
induces an automorphism $\tau|_M : M \to M$.
\item If $L/K$ is normal, then any $K$-algebra map $\sigma : M \to L$
extends to an automorphism of $L$.
\end{enumerate}

\label{lemma-quotient}
Let $X$ be a topological space. Let $Y$ be a set and let $f : X \to Y$
be a surjective map of sets. The quotient topology on $Y$ is the
topology characterized by each of the following statements:
\begin{enumerate}
\item it is the strongest topology on $Y$ such that $f$ is continuous,
\item a subset $V$ of $Y$ is open if and only if $f^{-1}(V)$ is open,
\item a subset $Z$ of $Y$ is closed if and only if $f^{-1}(Z)$ is closed.
\end{enumerate}

\label{lemma-sober-local}
Let $X$ be a topological space and let $(X_i)_{i\in I}$ be a covering of $X$.
\begin{enumerate}
\item Suppose $X_i$ is locally closed in $X$ for every $i\in I$. Then, $X$ is
Kolmogorov if and only if $X_i$ is Kolmogorov for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is
quasi-sober if and only if $X_i$ is quasi-sober for every $i\in I$.
\item Suppose $X_i$ is open in $X$ for every $i\in I$. Then, $X$ is sober if
and  only if $X_i$ is sober for every $i\in I$.
\end{enumerate}

\label{lemma-inverse-limit-spectral-spaces-nonempty}
Let $\mathcal{I}$ be a cofiltered category. Let $i \mapsto X_i$ be a diagram
of spectral spaces such that for $a : j \to i$ in $\mathcal{I}$
the corresponding map $f_a : X_j \to X_i$ is spectral.
\begin{enumerate}
\item Given nonempty subsets $Z_i \subset X_i$ closed in the constructible
topology with $f_a(Z_j) \subset Z_i$ for all $a : j \to i$ in $\mathcal{I}$,
then $\lim Z_i$ is nonempty.
\item If each $X_i$ is nonempty, then $X = \lim X_i$ is nonempty.
\end{enumerate}

\label{lemma-algebraically-closed}
Let $F$ be a field. The following are equivalent
\begin{enumerate}
\item $F$ is algebraically closed,
\item every irreducible polynomial over $F$ is linear,
\item every nonconstant polynomial over $F$ has a root,
\item every nonconstant polynomial over $F$ is a product of linear factors.
\end{enumerate}

\label{lemma-characterize-mono-epi}
Let $\mathcal{C}$ be a category, and let $f : X \to Y$ be
a morphism of $\mathcal{C}$. Then
\begin{enumerate}
\item $f$ is a monomorphism if and only if $X$ is the fibre
product $X \times_Y X$, and
\item $f$ is an epimorphism if and only if $Y$ is the pushout
$Y \amalg_X Y$.
\end{enumerate}

\label{lemma-lift-specializations-valuative}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item Specializations lift along any base change of $f$
\item The morphism $f$ satisfies the existence part of the
valuative criterion.
\end{enumerate}

\label{theorem-nullstellensatz}
Let $k$ be a field.
\begin{enumerate}
\item
\label{item-finite-kappa}
For any maximal ideal $\mathfrak m \subset k[x_1, \ldots, x_n]$
the field extension $\kappa(\mathfrak m)/k$ is finite.
\item
\label{item-polynomial-ring-Jacobson}
Any radical ideal $I \subset k[x_1, \ldots, x_n]$
is the intersection of maximal ideals containing it.
\end{enumerate}
The same is true in any finite type $k$-algebra.

statement:
Let $\mathcal{C}$ be a category. The construction of
Lemma \ref{lemma-setoid-fibres}
part (2) gives a functor
$$
F :
\left\{
\begin{matrix}
\text{the 2-category of categories}\\
\text{fibred in setoids over }\mathcal{C}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
\text{the category of categories}\\
\text{fibred in sets over }\mathcal{C}
\end{matrix}
\right\}
$$
(see
Definition \ref{definition-functor-into-2-category}).
This functor is an equivalence in the following sense:
\begin{enumerate}
\item for any two 1-morphisms $f, g : \mathcal{S}_1 \to \mathcal{S}_2$
with $F(f) = F(g)$ there exists a unique 2-isomorphism $f \to g$,
\item for any morphism $h : F(\mathcal{S}_1) \to F(\mathcal{S}_2)$
there exists a 1-morphism $f : \mathcal{S}_1 \to \mathcal{S}_2$
with $F(f) = h$, and
\item any category fibred in sets $\mathcal{S}$ is equal to $F(\mathcal{S})$.
\end{enumerate}
In particular, defining $F_i \in \textit{PSh}(\mathcal{C})$ by the
rule $F_i(U) = \Ob(\mathcal{S}_{i, U})/\cong$, we have
$$
\Mor_{\textit{Cat}/\mathcal{C}}(\mathcal{S}_1, \mathcal{S}_2)
\Big/
2\text{-isomorphism}
=
\Mor_{\textit{PSh}(\mathcal{C})}(F_1, F_2)
$$
More precisely, given any map $\phi : F_1 \to F_2$ there exists a
$1$-morphism $f : \mathcal{S}_1 \to \mathcal{S}_2$ which induces
$\phi$ on isomorphism classes of objects and
which is unique up to unique $2$-isomorphism.

statement_tex:
