\label{lemma-cohen}
Let $R$ be a ring.
\begin{enumerate}
\item An ideal $I \subset R$ maximal with respect to not being
finitely generated is prime.
\item If every prime ideal of $R$ is
finitely generated, then
every ideal of $R$ is finitely generated\footnote{Later we will say
that $R$ is Noetherian.}.
\end{enumerate}

\label{lemma-colimits}
The category of topological spaces has colimits and the forgetful functor
to sets commutes with them.

\label{lemma-directed-inverse-limit-finite-sober-spectral-spaces}
The inverse limit of a directed inverse system of finite sober
topological spaces is a spectral topological space.

\label{lemma-going-up-down-specialization}
Let $R \to S$ be a ring map.
\begin{enumerate}
\item $R \to S$ satisfies going down if and only if
generalizations lift along the map $\Spec(S) \to \Spec(R)$,
see Topology, Definition \ref{topology-definition-lift-specializations}.
\item $R \to S$ satisfies going up if and only if
specializations lift along the map $\Spec(S) \to \Spec(R)$,
see Topology, Definition \ref{topology-definition-lift-specializations}.
\end{enumerate}

\label{lemma-kernel-surjection-finite-free-onto-finite-presentation}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module of finite presentation.
\begin{enumerate}
\item If $\psi : \mathcal{O}_X^{\oplus r} \to \mathcal{F}$ is a surjection,
then $\Ker(\psi)$ is of finite type.
\item If $\theta : \mathcal{G} \to \mathcal{F}$ is surjective with
$\mathcal{G}$ of finite type, then $\Ker(\theta)$ is of finite type.
\end{enumerate}

statement:
The horizontal and vertical compositions have the following
properties
\begin{enumerate}
\item $\circ$ and $\star$ are associative,
\item the identity transformations $\text{id}_F$
are units for $\circ$,
\item the identity transformations of the identity functors
$\text{id}_{\text{id}_\mathcal{A}}$
are units for $\star$ and $\circ$, and
\item given a diagram
$$
\xymatrix{
\mathcal{A}
\rruppertwocell^F{t}
\ar[rr]_(.3){F'}
\rrlowertwocell_{F''}{t'}
& &
\mathcal{B}
\rruppertwocell^G{s}
\ar[rr]_(.3){G'}
\rrlowertwocell_{G''}{s'}
& &
\mathcal{C}
}
$$
we have $ (s' \circ s) \star (t' \circ t) = (s' \star t') \circ (s \star t)$.
\end{enumerate}

statement_tex:
\label{lemma-properties-2-cat-cats}
The horizontal and vertical compositions have the following
properties
\begin{enumerate}
\item $\circ$ and $\star$ are associative,
\item the identity transformations $\text{id}_F$
are units for $\circ$,
\item the identity transformations of the identity functors
$\text{id}_{\text{id}_\mathcal{A}}$
are units for $\star$ and $\circ$, and
\item given a diagram
$$
\xymatrix{
\mathcal{A}
\rruppertwocell^F{t}
\ar[rr]_(.3){F'}
\rrlowertwocell_{F''}{t'}
& &
\mathcal{B}
\rruppertwocell^G{s}
\ar[rr]_(.3){G'}
\rrlowertwocell_{G''}{s'}
& &
\mathcal{C}
}
$$
we have $ (s' \circ s) \star (t' \circ t) = (s' \star t') \circ (s \star t)$.
\end{enumerate}

\label{lemma-almost-finite-colimits-exist}
Let $\mathcal{C}$ be a category.
The following are equivalent:
\begin{enumerate}
\item Nonempty finite colimits exist in $\mathcal{C}$.
\item Coproducts of pairs and coequalizers exist in $\mathcal{C}$.
\item Coproducts of pairs and pushouts exist in $\mathcal{C}$.
\end{enumerate}

statement:
\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.

statement_tex:
\label{lemma-inverse-limit-top}
\begin{reference}
\cite[IV, Proposition 8.2.9]{EGA}
\end{reference}
Let $S = \lim S_i$ be the limit of a directed inverse system
of schemes with affine transition morphisms
(Lemma \ref{lemma-directed-inverse-system-has-limit}). Then
$S_{top} = \lim_i S_{i, top}$ where $S_{top}$
indicates the underlying topological space of the scheme $S$.

\label{lemma-spectral-inverse-limit-finite-sober-spaces}
A topological space is spectral if and only if it is a directed
inverse limit of finite sober topological spaces.

statement:
Let $A \to B \to C$ be ring maps.
\begin{enumerate}
\item If $A \to C$ is integral so is $B \to C$.
\item If $A \to C$ is finite so is $B \to C$.
\end{enumerate}

statement_tex:
\label{lemma-integral-permanence}
Let $A \to B \to C$ be ring maps.
\begin{enumerate}
\item If $A \to C$ is integral so is $B \to C$.
\item If $A \to C$ is finite so is $B \to C$.
\end{enumerate}

\label{lemma-characterize-finite-in-terms-of-integral}
Let $R \to S$ be a ring map. The following are equivalent
\begin{enumerate}
\item $R \to S$ is finite,
\item $R \to S$ is integral and of finite type, and
\item there exist $x_1, \ldots, x_n \in S$ which generate $S$ as an
algebra over $R$ such that each $x_i$ is integral over $R$.
\end{enumerate}

\label{theorem-characterize-proper}
\begin{reference}
In \cite[I, p. 75, Theorem 1]{Bourbaki} you can find:
(2) $\Leftrightarrow$ (4).
In \cite[I, p. 77, Proposition 6]{Bourbaki} you can find:
(2) $\Rightarrow$ (1).
\end{reference}
Let $f: X\to Y$ be a continuous map between
topological spaces. The following conditions are equivalent:
\begin{enumerate}
\item The map $f$ is quasi-proper and closed.
\item The map $f$ is Bourbaki-proper.
\item The map $f$ is universally closed.
\item The map $f$ is closed and $f^{-1}(y)$ is quasi-compact for any
$y\in Y$.
\end{enumerate}

\label{lemma-characterize-representable-fibred-category}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category fibred in groupoids.
\begin{enumerate}
\item $\mathcal{S}$ is representable if and only if
the following conditions are satisfied:
\begin{enumerate}
\item $\mathcal{S}$ is fibred in setoids, and
\item the presheaf $U \mapsto \Ob(\mathcal{S}_U)/\cong$ is
representable.
\end{enumerate}
\item If $\mathcal{S}$ is representable the pair $(X, j)$, where $j$ is the
equivalence $j : \mathcal{S} \to \mathcal{C}/X$, is uniquely determined
up to isomorphism.
\end{enumerate}

statement:
Let $R \to S$ be a ring map.
Let $f_1, \ldots, f_n \in R$ generate the unit ideal.
\begin{enumerate}
\item If each $R_{f_i} \to S_{f_i}$ is integral, so is $R \to S$.
\item If each $R_{f_i} \to S_{f_i}$ is finite, so is $R \to S$.
\end{enumerate}

statement_tex:
\label{lemma-integral-local}
Let $R \to S$ be a ring map.
Let $f_1, \ldots, f_n \in R$ generate the unit ideal.
\begin{enumerate}
\item If each $R_{f_i} \to S_{f_i}$ is integral, so is $R \to S$.
\item If each $R_{f_i} \to S_{f_i}$ is finite, so is $R \to S$.
\end{enumerate}

statement:
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item The space $X$ is quasi-compact.
\item Any subset of $X$ is retrocompact.
\end{enumerate}

statement_tex:
\label{lemma-Noetherian-quasi-compact}
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item The space $X$ is quasi-compact.
\item Any subset of $X$ is retrocompact.
\end{enumerate}

statement:
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is Noetherian, then $f(X)$ is Noetherian.
\item If $X$ is locally Noetherian and $f$ open, then $f(X)$ is
locally Noetherian.
\end{enumerate}

statement_tex:
\label{lemma-image-Noetherian}
Let $f : X \to Y$ be a continuous map of topological spaces.
\begin{enumerate}
\item If $X$ is Noetherian, then $f(X)$ is Noetherian.
\item If $X$ is locally Noetherian and $f$ open, then $f(X)$ is
locally Noetherian.
\end{enumerate}

\label{lemma-profinite}
Let $X$ be a topological space.
The following are equivalent
\begin{enumerate}
\item $X$ is a profinite space, and
\item $X$ is Hausdorff, quasi-compact, and totally disconnected.
\end{enumerate}
If this is true, then $X$ is a cofiltered limit of finite discrete
spaces.

statement:
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finite $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is injective.
\end{enumerate}

statement_tex:
\label{lemma-characterize-finite-module-hom}
Let $R$ be a ring. Let $N$ be an $R$-module. The following are equivalent
\begin{enumerate}
\item $N$ is a finite $R$-module,
\item for any filtered colimit $M = \colim M_i$ of $R$-modules the map
$\colim \Hom_R(N, M_i) \to \Hom_R(N, M)$ is injective.
\end{enumerate}

\label{lemma-ff}
\begin{slogan}
A flat module is faithfully flat if and only if it has nonzero fibers.
\end{slogan}
Let $M$ be a flat $R$-module.
The following are equivalent:
\begin{enumerate}
\item $M$ is faithfully flat,
\item for every nonzero $R$-module $N$, then tensor product $M \otimes_R N$
is nonzero,
\item for all $\mathfrak p \in \Spec(R)$
the tensor product $M \otimes_R \kappa(\mathfrak p)$ is nonzero, and
\item for all maximal ideals $\mathfrak m$ of $R$
the tensor product $M \otimes_R \kappa(\mathfrak m) = M/{\mathfrak m}M$
is nonzero.
\end{enumerate}

\label{lemma-integral-closure-stalks}
\begin{slogan}
An element of an algebra over a ring is integral over the ring
if and only if it is locally integral at every prime ideal of the ring.
\end{slogan}
Let $\varphi : R \to S$ be a ring map.
Let $x \in S$. The following are equivalent:
\begin{enumerate}
\item $x$ is integral over $R$, and
\item for every prime ideal $\mathfrak p \subset R$ the element
$x \in S_{\mathfrak p}$ is integral over $R_{\mathfrak p}$.
\end{enumerate}

\label{lemma-affine-reduced}
An affine scheme $\Spec(R)$ is reduced
if and only if $R$ is reduced.

\label{lemma-free-tensor-algebra}
Let $R$ be a ring. Let $M$ be an $R$-module.
If $M$ is a free $R$-module, so is each symmetric and exterior power.

\label{lemma-lift-nth-roots}
Let $R$ be a ring. Let $I \subset R$ be a locally nilpotent ideal.
Let $n \geq 1$ be an integer which is invertible in $R/I$. Then
\begin{enumerate}
\item the $n$th power map $1 + I \to 1 + I$, $1 + x \mapsto (1 + x)^n$
is a bijection,
\item a unit of $R$ is a $n$th power if and only if its image in $R/I$
is an $n$th power.
\end{enumerate}

\label{lemma-equivalence-categories}
A functor is an equivalence of categories if and only if it is both fully
faithful and essentially surjective.

\label{lemma-limits}
The category of topological spaces has limits and the forgetful functor
to sets commutes with them.

\label{lemma-inverse-limit-spectral-spaces-quasi-compact}
Let $\mathcal{I}$ be a category. Let $i \mapsto X_i$ be a diagram
of spectral spaces such that for $a : j \to i$ in $\mathcal{I}$
the corresponding map $f_a : X_j \to X_i$ is spectral.
\begin{enumerate}
\item Given subsets $Z_i \subset X_i$ closed in the constructible
topology with $f_a(Z_j) \subset Z_i$ for all $a : j \to i$ in $\mathcal{I}$,
then $\lim Z_i$ is quasi-compact.
\item The space $X = \lim X_i$ is quasi-compact.
\end{enumerate}

statement:
Let $X$ be a Hausdorff topological space.
\begin{enumerate}
\item If $E \subset X$ is quasi-compact, then it is closed.
\item If $E_1, E_2 \subset X$ are disjoint quasi-compact subsets
then there exists opens $E_i \subset U_i$ with $U_1 \cap U_2 = \emptyset$.
\end{enumerate}

statement_tex:
\label{lemma-quasi-compact-in-Hausdorff}
Let $X$ be a Hausdorff topological space.
\begin{enumerate}
\item If $E \subset X$ is quasi-compact, then it is closed.
\item If $E_1, E_2 \subset X$ are disjoint quasi-compact subsets
then there exists opens $E_i \subset U_i$ with $U_1 \cap U_2 = \emptyset$.
\end{enumerate}

\label{lemma-prepare-polynomial-ring-normal}
Let $R$ be a domain with fraction field $K$.
Suppose $f = \sum \alpha_i x^i$ is an
element of $K[x]$.
\begin{enumerate}
\item If $f$ is integral over $R[x]$
then all $\alpha_i$ are integral over $R$, and
\item If $f$ is almost integral over $R[x]$
then all $\alpha_i$ are almost integral over $R$.
\end{enumerate}

statement:
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item Any subset of $X$ with the induced topology is Noetherian.
\item The space $X$ has finitely many irreducible components.
\item Each irreducible component of $X$ contains a nonempty open of $X$.
\end{enumerate}

statement_tex:
\label{lemma-Noetherian}
Let $X$ be a Noetherian topological space.
\begin{enumerate}
\item Any subset of $X$ with the induced topology is Noetherian.
\item The space $X$ has finitely many irreducible components.
\item Each irreducible component of $X$ contains a nonempty open of $X$.
\end{enumerate}

\label{lemma-characterize-quasi-compact}
\begin{reference}
Combination of
\cite[I, p. 75, Lemme 1]{Bourbaki} and
\cite[I, p. 76, Corrolaire 1]{Bourbaki}.
\end{reference}
A topological space $X$ is quasi-compact if and only if the
projection map $Z \times X \to Z$ is closed for
any topological space $Z$.

statement:
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\begin{matrix}
X \to S\text{ of finite presentation}
\end{matrix}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

statement_tex:
\label{lemma-glueing-near-closed-point}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\begin{matrix}
X \to S\text{ of finite presentation}
\end{matrix}
\right\}
\longrightarrow
\left\{
\vcenter{
\xymatrix{
X' \ar[d] & Y' \ar[d] \ar[l] \ar[r] & Y \ar[d] \\
U & V \ar[l] \ar[r] & \Spec(\mathcal{O}_{S, s})
}
}
\right\}
$$
where on the right hand side we consider commutative diagrams
whose squares are cartesian and whose vertical arrows are
of finite presentation.

statement:
Let $E/F$ be a finite extension of fields. The following are equivalent
\begin{enumerate}
\item there exists a primitive element for $E$ over $F$, and
\item there are finitely many subextensions $E/K/F$.
\end{enumerate}
Moreover, (1) and (2) hold if $E/F$ is separable.

statement_tex:
\label{lemma-primitive-element}
Let $E/F$ be a finite extension of fields. The following are equivalent
\begin{enumerate}
\item there exists a primitive element for $E$ over $F$, and
\item there are finitely many subextensions $E/K/F$.
\end{enumerate}
Moreover, (1) and (2) hold if $E/F$ is separable.

\label{lemma-matrix-left-inverse}
Let $R$ be a ring. Let $n \geq m$. Let $A$ be an
$n \times m$ matrix with coefficients in $R$. Let $J \subset R$
be the ideal generated by the $m \times m$ minors of $A$.
\begin{enumerate}
\item For any $f \in J$ there exists a $m \times n$ matrix $B$
such that $BA = f 1_{m \times m}$.
\item If $f \in R$ and $BA = f 1_{m \times m}$ for some $m \times n$ matrix
$B$, then $f^m \in J$.
\end{enumerate}

\label{lemma-connected-fibres-quotient-topology-connected-components}
Let $f : X \to Y$ be a continuous map of topological spaces.
Assume that
\begin{enumerate}
\item all fibres of $f$ are connected, and
\item a set $T \subset Y$ is closed if and only if $f^{-1}(T)$ is closed.
\end{enumerate}
Then $f$ induces a bijection between the sets of connected
components of $X$ and $Y$.

\label{lemma-topological-group-colimits}
The category of topological groups has colimits and colimits commute
with the forgetful functor to the category of groups.

\label{lemma-topology-spec}
Let $R$ be a ring.
The topology on $X = \Spec(R)$ has the following properties:
\begin{enumerate}
\item $X$ is quasi-compact,
\item $X$ has a basis for the topology consisting of quasi-compact opens, and
\item the intersection of any two quasi-compact opens is quasi-compact.
\end{enumerate}

\label{lemma-separated}
Let $f : X \to Y$ be continuous map of topological spaces.
The following are equivalent:
\begin{enumerate}
\item $f$ is separated,
\item $\Delta(X) \subset X \times_Y X$ is a closed subset,
\item given distinct points $x, x' \in X$ mapping to the same point of
$Y$, there exist disjoint open neighbourhoods of $x$ and $x'$.
\end{enumerate}

\label{lemma-characterize-fibred-setoids-inertia}
Let $\mathcal{C}$ be a category.
Let $p : \mathcal{S} \to \mathcal{C}$ be a category fibred in groupoids.
The following are equivalent:
\begin{enumerate}
\item $p : \mathcal{S} \to \mathcal{C}$ is a category fibred in setoids, and
\item the canonical $1$-morphism $\mathcal{I}_\mathcal{S} \to \mathcal{S}$,
see (\ref{equation-inertia-structure-map}), is an equivalence (of categories
over $\mathcal{C}$).
\end{enumerate}

\label{lemma-constructible-stable-specialization-closed}
Let $X$ be a spectral space. Let $E \subset X$ be a subset closed
in the constructible topology (for example constructible).
\begin{enumerate}
\item If $x \in \overline{E}$, then $x$ is the specialization of a point of
$E$.
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E' \subset X$ is open in the constructible topology
(for example constructible) and stable under generalization, then $E'$ is open.
\end{enumerate}

\label{lemma-rephrase}
Let $\Sch_{fppf}$ be a big fppf site.
Let $S \to S'$ be a morphism of this site.
Let $F'$ be a sheaf on $(\Sch/S')_{fppf}$.
The following are equivalent:
\begin{enumerate}
\item The restriction $F'|_{(\Sch/S)_{fppf}}$
is an algebraic space over $S$, and
\item the sheaf $h_S \times F'$ is an algebraic space over $S'$.
\end{enumerate}

\label{lemma-skyscraper-stalks}
Let $X$ be a topological space, $x \in X$ a point, and
$A$ a set. For any point $x' \in X$ the stalk of the
skyscraper sheaf at $x$ with value $A$ at $x'$ is
$$
(i_{x, *}A)_{x'} =
\left\{
\begin{matrix}
A & \text{if} & x' \in \overline{\{x\}} \\
\{*\} & \text{if} & x' \not\in \overline{\{x\}}
\end{matrix}
\right.
$$
A similar description holds for the case of
abelian groups, algebraic structures and
sheaves of modules.

\label{lemma-quasi-compact-affine}
Let $f : X \to S$ be a morphism of schemes.
The following are equivalent
\begin{enumerate}
\item $f : X \to S$ is quasi-compact,
\item the inverse image of every affine open is quasi-compact, and
\item there exists some affine open covering $S = \bigcup_{i \in I} U_i$
such that $f^{-1}(U_i)$ is quasi-compact for all $i$.
\end{enumerate}

\label{lemma-ideal-in-localization}
\begin{slogan}
Ideals in the localization of a ring are localizations of ideals.
\end{slogan}
Each ideal $I'$ of $S^{-1}A$ takes the form $S^{-1}I$, where one can
take $I$ to be the inverse image of $I'$ in $A$.

